import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const l="/assets/zh-cn_formulaimage_0000002182888708.D8oPzwqy.png",p="/assets/zh-cn_formulaimage_0000002228789689.Dhu6Mcq8.png",m=JSON.parse('{"title":"Tan","description":"","frontmatter":{},"headers":[{"level":1,"title":"Tan","slug":"tan"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/Tan接口/Tan.md","filePath":"api/SIMD-API/高阶API/数学计算/Tan接口/Tan.md"}'),i={name:"api/SIMD-API/高阶API/数学计算/Tan接口/Tan.md"};function o(r,a,d,c,h,u){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="tan" tabindex="-1">Tan <a class="header-anchor" href="#tan" aria-label="Permalink to &quot;Tan&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>按元素做正切函数计算，计算公式如下：</p><p><img src="'+l+'" alt=""></p><p>Tan(x)的泰勒展开式为：</p><p><img src="'+p+`" alt=""></p><p>其中B2n是伯努利数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><ul><li><p>源操作数Tensor全部/部分参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void Tan(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t calCount)</span></span></code></pre></div></li><li><p>源操作数Tensor全部参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void Tan(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer)</span></span></code></pre></div></li></ul></li><li><p>接口框架申请临时空间</p><ul><li><p>源操作数Tensor全部/部分参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void Tan(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor, const uint32_t calCount)</span></span></code></pre></div></li><li><p>源操作数Tensor全部参与计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isReuseSource = false&gt;</span></span>
<span class="line"><span>__aicore__ inline void Tan(const LocalTensor&lt;T&gt;&amp; dstTensor, const LocalTensor&lt;T&gt;&amp; srcTensor)</span></span></code></pre></div></li></ul></li></ul><p>由于该接口的内部实现中涉及复杂的数学计算，需要额外的临时空间来存储计算过程中的中间变量。临时空间支持<strong>接口框架申请</strong>和开发者<strong>通过sharedTmpBuffer入参传入</strong>两种方式。</p><ul><li><p>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</p></li><li><p>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</p></li></ul><p>接口框架申请的方式，开发者需要预留临时空间；通过sharedTmpBuffer传入的情况，开发者需要为sharedTmpBuffer申请空间。临时空间大小BufferSize的获取方式如下：通过<a href="./GetTanMaxMinTmpSize.html">GetTanMaxMinTmpSize</a>中提供的GetTanMaxMinTmpSize接口获取需要预留空间的大小。</p><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr><tr><td>isReuseSource</td><td>是否允许修改源操作数。该参数预留，传入默认值false即可。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dstTensor</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>srcTensor</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 临时空间大小BufferSize的获取方式请参考GetTanMaxMinTmpSize。</td></tr><tr><td>calCount</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>输入数据限制在(-65504.0, 65504.0)范围内。</p></li><li><p><strong>不支持源操作数与目的操作数地址重叠。</strong></p></li><li><p>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</p></li><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// dstLocal: 存放Tan计算结果的Tensor</span></span>
<span class="line"><span>// srcLocal: 存放Tan计算输入的Tensor</span></span>
<span class="line"><span>// sharedTmpBuffer: 存放Tan计算过程中临时缓存的Tensor</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 接口框架申请临时空间，全部参与计算</span></span>
<span class="line"><span>AscendC::Tan(dstLocal, srcLocal);</span></span>
<span class="line"><span>// 接口框架申请临时空间，部分参与计算, 需要参与计算的元素个数为512</span></span>
<span class="line"><span>AscendC::Tan(dstLocal, srcLocal, 512);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，全部参与计算</span></span>
<span class="line"><span>AscendC::Tan(dstLocal, srcLocal, sharedTmpBuffer);</span></span>
<span class="line"><span>// 通过sharedTmpBuffer入参传入临时空间，部分参与计算, 需要参与计算的元素个数为512</span></span>
<span class="line"><span>AscendC::Tan(dstLocal, srcLocal, sharedTmpBuffer, 512);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal): </span></span>
<span class="line"><span>[-2.56 -2.55 -2.54 ... 0. ... 2.53  2.54  2.55]</span></span>
<span class="line"><span>输出数据(dstLocal): </span></span>
<span class="line"><span>[0.6567  0.671  0.688 ... -0.702  -0.688  -0.671 ]</span></span></code></pre></div>`,27)])])}const g=t(i,[["render",o]]);export{m as __pageData,g as default};
